
BEGIN;

-- 1. SIGLAS DE UF

-- 2. MUNICIPIOS (DOIS PAPEIS, UMA TABELA)

-- 3. SUPERFICIES DE PISTA

-- 4. TIPOS DE OPERACAO

-- 5. PERFIS RBAC 153

-- 6. CATEGORIAS DE OPERACAO

-- 7. TEXTOS DE RESTRICAO

-- 8. AERODROMOS (809 REGISTROS)

-- 9. PISTAS (653 REGISTROS)

-- 10. OPERACAO DIURNA/NOTURNA (1163 VINCULOS)

-- 11. CLASSIFICACAO RBAC (71 REGISTROS)

-- 12. CATEGORIAS POR AERODROMO (13 VINCULOS)

-- 13. RESTRICOES POR AERODROMO (19 VINCULOS)

-- 14. Sincronizar sequencias das chaves geradas.
SELECT setval(pg_get_serial_sequence('municipio', 'municipio_id'), (SELECT max(municipio_id) FROM municipio), true);
SELECT setval(pg_get_serial_sequence('superficie_pista', 'superficie_pista_id'), (SELECT max(superficie_pista_id) FROM superficie_pista), true);
SELECT setval(pg_get_serial_sequence('tipo_operacao', 'tipo_operacao_id'), (SELECT max(tipo_operacao_id) FROM tipo_operacao), true);
SELECT setval(pg_get_serial_sequence('perfil_operacional', 'perfil_operacional_id'), (SELECT max(perfil_operacional_id) FROM perfil_operacional), true);
SELECT setval(pg_get_serial_sequence('categoria_operacao', 'categoria_operacao_id'), (SELECT max(categoria_operacao_id) FROM categoria_operacao), true);
SELECT setval(pg_get_serial_sequence('restricao', 'restricao_id'), (SELECT max(restricao_id) FROM restricao), true);

-- 15. CONFERENCIA: interromper e desfazer TODA a carga se houver divergencia.
DO $verificacao$
DECLARE divergencias TEXT;
BEGIN
    WITH contagens(tabela, esperado, carregado) AS (
        SELECT 'estado', 7::BIGINT, COUNT(*) FROM estado UNION ALL
        SELECT 'municipio', 242::BIGINT, COUNT(*) FROM municipio UNION ALL
        SELECT 'superficie_pista', 9::BIGINT, COUNT(*) FROM superficie_pista UNION ALL
        SELECT 'tipo_operacao', 3::BIGINT, COUNT(*) FROM tipo_operacao UNION ALL
        SELECT 'perfil_operacional', 3::BIGINT, COUNT(*) FROM perfil_operacional UNION ALL
        SELECT 'categoria_operacao', 3::BIGINT, COUNT(*) FROM categoria_operacao UNION ALL
        SELECT 'restricao', 8::BIGINT, COUNT(*) FROM restricao UNION ALL
        SELECT 'aerodromo', 809::BIGINT, COUNT(*) FROM aerodromo UNION ALL
        SELECT 'pista', 653::BIGINT, COUNT(*) FROM pista UNION ALL
        SELECT 'aerodromo_operacao', 1163::BIGINT, COUNT(*) FROM aerodromo_operacao UNION ALL
        SELECT 'aerodromo_rbac', 71::BIGINT, COUNT(*) FROM aerodromo_rbac UNION ALL
        SELECT 'aerodromo_categoria_operacao', 13::BIGINT, COUNT(*) FROM aerodromo_categoria_operacao UNION ALL
        SELECT 'aerodromo_restricao', 19::BIGINT, COUNT(*) FROM aerodromo_restricao
    )
    SELECT string_agg(format('%s: esperado %s / encontrado %s', tabela, esperado, carregado), '; ')
    INTO divergencias FROM contagens WHERE esperado <> carregado;
    IF divergencias IS NOT NULL THEN
        RAISE EXCEPTION 'Carga ANAC divergente: %', divergencias;
    END IF;
END
$verificacao$;

COMMIT;

-- Conferencia de contagem para apresentar no pgAdmin (13 linhas, tudo OK).
WITH contagens(tabela, esperado, carregado) AS (
    SELECT 'estado', 7::BIGINT, COUNT(*) FROM estado UNION ALL
    SELECT 'municipio', 242::BIGINT, COUNT(*) FROM municipio UNION ALL
    SELECT 'superficie_pista', 9::BIGINT, COUNT(*) FROM superficie_pista UNION ALL
    SELECT 'tipo_operacao', 3::BIGINT, COUNT(*) FROM tipo_operacao UNION ALL
    SELECT 'perfil_operacional', 3::BIGINT, COUNT(*) FROM perfil_operacional UNION ALL
    SELECT 'categoria_operacao', 3::BIGINT, COUNT(*) FROM categoria_operacao UNION ALL
    SELECT 'restricao', 8::BIGINT, COUNT(*) FROM restricao UNION ALL
    SELECT 'aerodromo', 809::BIGINT, COUNT(*) FROM aerodromo UNION ALL
    SELECT 'pista', 653::BIGINT, COUNT(*) FROM pista UNION ALL
    SELECT 'aerodromo_operacao', 1163::BIGINT, COUNT(*) FROM aerodromo_operacao UNION ALL
    SELECT 'aerodromo_rbac', 71::BIGINT, COUNT(*) FROM aerodromo_rbac UNION ALL
    SELECT 'aerodromo_categoria_operacao', 13::BIGINT, COUNT(*) FROM aerodromo_categoria_operacao UNION ALL
    SELECT 'aerodromo_restricao', 19::BIGINT, COUNT(*) FROM aerodromo_restricao
)
SELECT tabela, esperado, carregado,
       CASE WHEN esperado = carregado THEN 'OK' ELSE 'DIVERGENTE' END AS resultado
FROM contagens ORDER BY tabela;
